def add(a: int, b: int) -> int:
    try:
        if not isinstance(a, int) or not isinstance(b, int):
            raise TypeError("Both parameters must be integers")
        return a + b
    except Exception as exc:
        raise TypeError(f"Error adding {a} and {b}: {exc}") from exc

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each value is collected at most once, even if both paths pass through it.

    Args:
        N (int): The size of the grid (N x N).
        grid_values (List[Tuple[int, int, int]]): A list of tuples where each tuple
            contains (x-coordinate, y-coordinate, value). The list is terminated
            by a tuple with all zeros, which should not be used.

    Returns:
        int: The maximum sum of values collected on the two paths.
    """
    # Validate input
    if N <= 0:
        return 0
    # Create grid with 1-based indexing
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] += val  # Sum values if duplicates appear

    # Special case: single cell grid
    if N == 1:
        return grid[1][1]

    INF_NEG = -10**12
    # dp[i1][i2] represents maximum sum when first path is at (i1, j1)
    # and second path is at (i2, j2) after k steps, where j1 = k - i1,
    # j2 = k - i2. We'll use a 2D array for the current step.
    dp = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = grid[1][1]

    for step in range(2, 2 * N + 1):
        newdp = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
        for i1 in range(1, N + 1):
            j1 = step - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(1, N + 1):
                j2 = step - i2
                if j2 < 1 or j2 > N:
                    continue
                best = INF_NEG
                # Explore four possible previous moves
                for pi1 in (i1, i1 - 1):
                    if pi1 < 1 or pi1 > N:
                        continue
                    for pi2 in (i2, i2 - 1):
                        if pi2 < 1 or pi2 > N:
                            continue
                        val = dp[pi1][pi2]
                        if val > best:
                            best = val
                if best == INF_NEG:
                    continue
                add = 0
                if i1 == i2 and j1 == j2:
                    add = grid[i1][j1]
                else:
                    add = grid[i1][j1] + grid[i2][j2]
                newdp[i1][i2] = best + add
        dp = newdp

    result = dp[N][N]
    return result if result != INF_NEG else 0

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Parameters:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    # Validate inputs
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer.")
    if not isinstance(coeffs, list):
        raise ValueError("coeffs must be a list.")
    if len(coeffs) != n + 1:
        raise ValueError(f"Expected coeffs list of length {n + 1}, got {len(coeffs)}.")

    result_parts = []
    first_term = True

    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if first_term:
            sign_str = '-' if coeff < 0 else ''
        else:
            sign_str = '-' if coeff < 0 else '+'

        # Determine coefficient portion
        abs_coeff = abs(coeff)
        if degree == 0:
            coeff_str = str(abs_coeff)
        else:
            coeff_str = '' if abs_coeff == 1 else str(abs_coeff)

        # Determine variable portion
        if degree == 0:
            var_str = ''
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = f'x^{degree}'

        term = f"{sign_str}{coeff_str}{var_str}"
        result_parts.append(term)
        first_term = False

    if not result_parts:
        return '0'

    return ''.join(result_parts)

def select_volunteers(n: int, m: int, applicants: List[Tuple[int, int]]) -> Tuple[int, List[Tuple[int, int]]]:
    # Input validation
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    if not isinstance(m, int) or m < 0:
        raise ValueError("m must be a non-negative integer")
    if not isinstance(applicants, list):
        raise ValueError("applicants must be a list")
    if len(applicants) != n:
        raise ValueError("Length of applicants does not match n")
    for i, a in enumerate(applicants):
        if not isinstance(a, tuple) or len(a) != 2:
            raise ValueError(f"Applicant at index {i} is not a tuple of length 2")
        reg, score = a
        if not isinstance(reg, int) or not isinstance(score, int):
            raise ValueError(f"Applicant at index {i} contains non-integer values")

    # Sort applicants: descending by score, ascending by registration number for ties
    sorted_applicants = sorted(applicants, key=lambda x: (-x[1], x[0]))

    # Determine cutoff: floor(1.5 * m)th highest score
    cutoff_count = int(1.5 * m)
    if cutoff_count <= 0:
        # If no volunteers planned, set cutoff extremely low so that candidates are not selected
        cutoff_score = -1
    else:
        idx = cutoff_count - 1
        if idx >= len(sorted_applicants):
            idx = len(sorted_applicants) - 1
        cutoff_score = sorted_applicants[idx][1]

    # Filter qualified applicants
    qualified = [ap for ap in sorted_applicants if ap[1] >= cutoff_score]

    return cutoff_score, qualified

def decode(encoded: str, original: str, message: str) -> str:
    # The cipher must be a bijective mapping from encoded letters to original letters
    if len(encoded) != len(original):
        return "Failed"
    mapping = {}
    used_original = set()
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"  # contradictory mapping
        else:
            if o in used_original:
                return "Failed"  # two encoded chars map to same original
            mapping[e] = o
            used_original.add(o)
    if len(mapping) != 26:
        return "Failed"  # mapping does not cover all letters
    try:
        return ''.join(mapping[ch] for ch in message)
    except KeyError:
        return "Failed"

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to 10 steps. Returns minimum number of steps or "NO ANSWER!" if impossible.
    """
    # Validate basic input
    if not isinstance(A, str) or not isinstance(B, str) or not isinstance(rules, list):
        return "NO ANSWER!"
    # Early exit
    if A == B:
        return 0
    max_depth = 10
    queue = [(A, 0)]
    visited = {A}
    while queue:
        current, depth = queue.pop(0)
        if depth >= max_depth:
            continue
        for src, tgt in rules:
            if not isinstance(src, str) or not isinstance(tgt, str) or len(src) == 0:
                continue
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx+len(src):]
                if new_str == B:
                    return depth + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, depth + 1))
                start = idx + 1  # move past this occurrence
    return "NO ANSWER!"

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.

    Each rule allows a single digit to be transformed into another. A breadth-first search
    (BFS) is used to explore all possible transformations. The function returns the count
    of unique numbers that can be generated from the original number, including the number itself.

    Args:
        n (int): The original integer number to transform.
        rules (list of tuples): A list of transformation rules, where each rule is represented
            as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
        int: The total count of unique numbers that can be generated.

    Examples:
        >>> generate_numbers(234, [(2, 5), (3, 6)])
        4
        >>> generate_numbers(100, [(1, 9)])
        2
    """
    # Basic validation
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list of tuples")
    for rule in rules:
        if (not isinstance(rule, tuple)) or len(rule) != 2:
            raise ValueError("Each rule must be a tuple of two integers")
        if not (isinstance(rule[0], int) and isinstance(rule[1], int)):
            raise ValueError("Rule elements must be integers")
        if not (0 <= rule[0] <= 9 and 0 <= rule[1] <= 9):
            raise ValueError("Rule digits must be between 0 and 9")
    # Build mapping from source digit to list of target digits
    mapping = {}
    for src, tgt in rules:
        mapping.setdefault(str(src), []).append(str(tgt))

    start_str = str(n)
    visited = set([start_str])
    queue = [start_str]

    while queue:
        current = queue.pop(0)
        # Iterate over each digit position
        for i, ch in enumerate(current):
            if ch in mapping:
                for tgt in mapping[ch]:
                    new_num = current[:i] + tgt + current[i + 1:]
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)
    return len(visited)

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    try:
        if heights is None:
            raise ValueError("Input 'heights' cannot be None.")
        if not isinstance(heights, list):
            raise TypeError("Input 'heights' must be a list of integers.")
        if any(not isinstance(h, int) for h in heights):
            raise TypeError("All elements in 'heights' must be integers.")
    except Exception as e:
        raise ValueError(f"Invalid input: {e}")

    n = len(heights)
    if n <= 1:
        return 0

    # Longest increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Maximum length of a bitonic subsequence
    max_bitonic = max(lis[i] + lds[i] - 1 for i in range(n))

    return n - max_bitonic
